#!/usr/bin/env python3
"""Package completed native GAME evidence, preserving raw errors and source labels."""
import argparse,hashlib,json,shutil,datetime
from pathlib import Path
from PIL import Image,ImageDraw,ImageFont
p=argparse.ArgumentParser();p.add_argument('--raw',type=Path,required=True);p.add_argument('--out',type=Path,required=True);a=p.parse_args();r=json.loads((a.raw/'report.json').read_text());assert r['complete'];a.out.mkdir(parents=True,exist_ok=True);sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
for name in ['report.json','atlas-metadata.json','runner-executed.cjs']:
 if (a.raw/name).exists():shutil.copy2(a.raw/name,a.out/name)
items=[]
for district in r['districts']:
 captures=[c for case in district['cases'] for c in case['captures']]+[row['capture'] for row in district['drone'] if 'capture' in row]
 for capture in captures:
  original=a.raw/capture['file'];assert sha(original)==capture['sha256'];im=Image.open(original).convert('RGB');name=original.stem+'.jpg';target=a.out/'images'/name;target.parent.mkdir(exist_ok=True);im.save(target,quality=90);thumb=a.out/'thumbs'/name;thumb.parent.mkdir(exist_ok=True);im.copy().resize((320,180),Image.Resampling.LANCZOS).save(thumb,quality=86);f=capture['frames'][-1];label=capture['label'];items.append({'id':original.stem,'district':district['id'],'label':label,'captureType':'game-perspective-context','comparisonCompatible':False,'image':'images/'+name,'thumbnail':'thumbs/'+name,'sha256':sha(target),'thumbnailSha256':sha(thumb),'originalPNG':{'file':capture['file'],'sha256':capture['sha256']},'gameSourceCommit':r['sourceCommit'],'capturedAt':capture['capturedAt'],'pose':{'x':f['camera']['position'][0],'y':f['camera']['position'][1],'z':f['camera']['position'][2],'quaternion':f['camera']['quaternion']},'playerPose':f['pose'],'drone':f['drone'],'camera':f['camera'],'conditions':f['conditions'],'staticCamera':False,'controllerExercised':not label.endswith('chapter-start'),'controllerNote':'Initial source-road placement with native idle controller' if label.endswith('chapter-start') else 'Native physical input/controller route or view-following drone flight; no camera-plane, population or LOD override','performanceFrames':[{k:frame[k] for k in ['calls','triangles','passes']} for frame in capture['frames']],'architecturalParity':False})
for item in items:
 item['conditions']['steadyState']=False
 if item['label'].startswith('drone-'):
  item['conditions']['visibleTransition']='Winter snow to selected summer clear: residual snow particles remain visible. This is flight/controller evidence rather than settled clear-weather visual acceptance.'
manifest={'schemaVersion':1,'gameSourceCommit':r['sourceCommit'],'captureType':'game-perspective-context','comparisonCompatible':False,'generatedAt':datetime.datetime.now(datetime.timezone.utc).isoformat(),'title':'Unirii and Otopeni bounded native approach and drone context','description':'Native high-quality driving and drone evidence; separate from the dated north-up aerial comparison grids. These are targeted controller/render cases, not a complete street survey or a claim of architectural parity.','items':items,'rawReport':{'path':'report.json','sha256':sha(a.out/'report.json')},'runtimeErrors':r['errors'],'rawFailures':r['failures'],'observationNotes':['The raw first execution compares active vehicle arrays across time profiles. Night moves vehicles into the native preserved pool; combined IDs require the separate observer confirmation. The raw assertion is retained rather than erased.','The raw first execution labels unrecognised orthographic cameras shadow. Its18 fullscreen post draws are included in totals; only sun-shadow identifies the actual sun shadow camera. Full attribution uses exact light camera identity.','Captured logical frames include production mirror, main, shadow and post work. SoftwareGL timings are diagnostics, not hardware FPS evidence.','The two frames at each view include condition/reflection transition work; no fully-settled environment or15minute soak claim is made.','The205 aerial items retain their0775 capture revisions and their complete paired review with gaps; thesec78 native cases do not relabel them.']}
(a.out/'context-manifest.json').write_text(json.dumps(manifest,indent=2)+'\n');font=ImageFont.truetype('/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf',14)
for start in range(0,len(items),6):
 batch=items[start:start+6];sheet=Image.new('RGB',(1280,((len(batch)+1)//2)*390),(18,18,18));draw=ImageDraw.Draw(sheet)
 for k,item in enumerate(batch):
  x=k%2*640;y=k//2*390;draw.text((x+5,y+5),item['id'],font=font,fill='white');sheet.paste(Image.open(a.out/item['image']).resize((640,360)),(x,y+27))
 q=a.out/'contact-sheets'/f'native-{start//6+1:02}.jpg';q.parent.mkdir(exist_ok=True);sheet.save(q,quality=92)
print(json.dumps({'source':r['sourceCommit'],'items':len(items),'manifestSha256':sha(a.out/'context-manifest.json'),'rawComplete':r['complete'],'rawFailuresRetained':len(r['failures'])}))
